function(container, apiUrl, tables) {
    // 業務ロジックのインポート
    const {
        collectSalesData,
        classifySalesDataByProduct,
        classifySalesDataByStore,
        filterValidProductData,
        collectWeatherData,
        collectEventData,
        collectSeasonalData,
        analyzeCorrelationSalesWeather,
        analyzeCorrelationSalesEvent,
        analyzeCorrelationSalesSeason,
        compareWithHistoricalData,
        findAlternativeComparisonData,
        validateComparisonPeriod
    } = window.aivicLogic.ai;

    // DOM要素の取得
    const productSelect = container.querySelector('#productSelect');
    const storeSelect = container.querySelector('#storeSelect');
    const startDateInput = container.querySelector('#startDate');
    const endDateInput = container.querySelector('#endDate');
    const forecastPeriodInput = container.querySelector('#forecastPeriod');
    const predictButton = container.querySelector('#predictButton');
    const resultsTable = container.querySelector('#resultsTable tbody');
    const accuracyDisplay = container.querySelector('#accuracyDisplay');
    const correlationDisplay = container.querySelector('#correlationDisplay');

    // 初期データの読み込み
    async function loadInitialData() {
        try {
            const [products, stores] = await Promise.all([
                window.aivicApi.list('products'),
                window.aivicApi.list('stores')
            ]);

            // 商品選択肢の設定
            productSelect.innerHTML = '<option value="">全商品</option>';
            products.forEach(product => {
                const option = document.createElement('option');
                option.value = product.id;
                option.textContent = product.name;
                productSelect.appendChild(option);
            });

            // 店舗選択肢の設定
            storeSelect.innerHTML = '<option value="">全店舗</option>';
            stores.forEach(store => {
                const option = document.createElement('option');
                option.value = store.id;
                option.textContent = store.name;
                storeSelect.appendChild(option);
            });

        } catch (error) {
            window.aivicNotify.error('初期データの読み込みに失敗しました: ' + error.message);
        }
    }

    // 需要予測実行
    async function executeDemandForecast() {
        try {
            const productId = productSelect.value;
            const storeId = storeSelect.value;
            const startDate = startDateInput.value;
            const endDate = endDateInput.value;
            const forecastPeriod = parseInt(forecastPeriodInput.value) || 30;

            if (!startDate || !endDate) {
                window.aivicNotify.error('開始日と終了日を入力してください');
                return;
            }

            // 比較期間の妥当性チェック
            const validationResult = validateComparisonPeriod(startDate, endDate, forecastPeriod);
            if (!validationResult.isValid) {
                window.aivicNotify.error(validationResult.message);
                return;
            }

            // 売上データの収集
            const salesData = await collectSalesData(startDate, endDate, productId, storeId);

            // 商品・店舗別の分類
            let classifiedData = salesData;
            if (productId) {
                classifiedData = classifySalesDataByProduct(classifiedData, productId);
            }
            if (storeId) {
                classifiedData = classifySalesDataByStore(classifiedData, storeId);
            }

            // 有効な商品データのフィルタリング
            const validData = filterValidProductData(classifiedData);

            // 外部データの収集
            const [weatherData, eventData, seasonalData] = await Promise.all([
                collectWeatherData(startDate, endDate),
                collectEventData(startDate, endDate),
                collectSeasonalData(startDate, endDate)
            ]);

            // 相関分析
            const weatherCorrelation = analyzeCorrelationSalesWeather(validData, weatherData);
            const eventCorrelation = analyzeCorrelationSalesEvent(validData, eventData);
            const seasonalCorrelation = analyzeCorrelationSalesSeason(validData, seasonalData);

            // 過去データとの比較
            let comparisonResult;
            try {
                comparisonResult = await compareWithHistoricalData(validData, startDate, endDate);
            } catch (error) {
                // 代替比較データの検索
                comparisonResult = await findAlternativeComparisonData(validData, startDate, endDate);
            }

            // 予測結果の表示
            displayForecastResults(validData, forecastPeriod, comparisonResult);

            // 精度情報の表示
            displayAccuracy(comparisonResult.accuracy);

            // 相関情報の表示
            displayCorrelations({
                weather: weatherCorrelation,
                event: eventCorrelation,
                seasonal: seasonalCorrelation
            });

            window.aivicNotify.success('需要予測が完了しました');

        } catch (error) {
            window.aivicNotify.error('需要予測の実行に失敗しました: ' + error.message);
        }
    }

    // 予測結果の表示
    function displayForecastResults(salesData, forecastPeriod, comparisonResult) {
        resultsTable.innerHTML = '';

        // 予測データの生成（簡易的な実装）
        const avgSales = salesData.reduce((sum, data) => sum + data.quantity, 0) / salesData.length;
        const trend = comparisonResult.trend || 1.0;

        for (let i = 1; i <= forecastPeriod; i++) {
            const forecastDate = new Date();
            forecastDate.setDate(forecastDate.getDate() + i);

            const predictedQuantity = Math.round(avgSales * trend * (1 + Math.random() * 0.2 - 0.1));

            const row = document.createElement('tr');
            row.innerHTML = `
                <td>${forecastDate.toISOString().split('T')[0]}</td>
                <td>${predictedQuantity}</td>
                <td>${(predictedQuantity * 100).toLocaleString()}円</td>
                <td>予測</td>
            `;
            resultsTable.appendChild(row);
        }
    }

    // 精度情報の表示
    function displayAccuracy(accuracy) {
        if (accuracyDisplay && accuracy) {
            accuracyDisplay.innerHTML = `
                <div class="accuracy-info">
                    <h4>予測精度</h4>
                    <p>MAPE: ${(accuracy.mape * 100).toFixed(2)}%</p>
                    <p>RMSE: ${accuracy.rmse.toFixed(2)}</p>
                    <p>信頼度: ${(accuracy.confidence * 100).toFixed(1)}%</p>
                </div>
            `;
        }
    }

    // 相関情報の表示
    function displayCorrelations(correlations) {
        if (correlationDisplay) {
            correlationDisplay.innerHTML = `
                <div class="correlation-info">
                    <h4>相関分析結果</h4>
                    <p>天候との相関: ${correlations.weather.coefficient.toFixed(3)}</p>
                    <p>イベントとの相関: ${correlations.event.coefficient.toFixed(3)}</p>
                    <p>季節性との相関: ${correlations.seasonal.coefficient.toFixed(3)}</p>
                </div>
            `;
        }
    }

    // イベントリスナーの設定
    if (predictButton) {
        predictButton.addEventListener('click', executeDemandForecast);
    }

    // 初期化実行
    loadInitialData();
}
